<?php
namespace App\Services;
use App\Enums\AgreementStatus;use App\Models\AgencySetting;use App\Models\Agreement;use App\Models\AgreementTemplate;use App\Models\Assignment;use App\Models\Customer;use App\Models\CustomerRequirement;use App\Models\Worker;use Carbon\Carbon;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class AgreementService
{
 public function create(array $data,int $actorId):Agreement{return DB::transaction(function()use($data,$actorId){$resolved=$this->resolve($data);$agency=AgencySetting::firstOrFail();$customer=$resolved['customer'];$worker=$resolved['worker'];$assignment=$resolved['assignment'];$requirement=$resolved['requirement'];if($assignment){Assignment::whereKey($assignment->id)->lockForUpdate()->firstOrFail();if(Agreement::where('assignment_id',$assignment->id)->where('status','!=',AgreementStatus::Cancelled->value)->exists())throw ValidationException::withMessages(['assignment_id'=>'This assignment already has a current agreement.']);}$agreement=Agreement::create(['agreement_code'=>'PENDING-'.Str::uuid(),'customer_id'=>$customer->id,'customer_requirement_id'=>$requirement?->id,'assignment_id'=>$assignment?->id,'worker_id'=>$worker?->id,'service_id'=>$assignment?->service_id??$requirement?->service_id,'duty_type_id'=>$assignment?->duty_type_id??$requirement?->duty_type_id,'agreement_date'=>$data['agreement_date'],'start_date'=>$data['start_date']??$assignment?->assignment_start_date,'end_date'=>$data['end_date']??$assignment?->assignment_end_date,'tenure_text'=>$data['tenure_text']??$this->tenure($data['start_date']??$assignment?->assignment_start_date,$data['end_date']??$assignment?->assignment_end_date),'monthly_salary'=>$data['monthly_salary']??$assignment?->monthly_salary,'monthly_agency_service_charge'=>$data['monthly_agency_service_charge']??$assignment?->agency_service_charge,'working_hours_text'=>$data['working_hours_text']??$assignment?->working_hours_text??$requirement?->workingCondition?->working_hours_text,'monthly_leave_text'=>$data['monthly_leave_text']??$requirement?->workingCondition?->leave_details,'work_location'=>$data['work_location']??$assignment?->work_location,'gender_preference'=>$requirement?->required_gender,'house_type'=>$requirement?->householdDetail?->house_type,'status'=>AgreementStatus::Draft,'terms_snapshot'=>$data['terms_snapshot'],'customer_name_snapshot'=>$data['customer_name_snapshot']??$customer->name,'customer_address_snapshot'=>$data['customer_address_snapshot']??$this->customerAddress($customer),'customer_mobile_snapshot'=>$data['customer_mobile_snapshot']??$customer->mobile_number,'customer_email_snapshot'=>$data['customer_email_snapshot']??$customer->email,'worker_name_snapshot'=>$worker?->name,'worker_code_snapshot'=>$worker?->worker_code,'agency_name_snapshot'=>$agency->business_name,'agency_address_snapshot'=>$this->agencyAddress($agency),'agency_phone_snapshot'=>$agency->phone_primary,'agency_email_snapshot'=>$agency->email,'agency_gst_snapshot'=>$agency->gst_number,'authorized_person_name'=>$data['authorized_person_name']??$agency->owner_authorized_person,'created_by'=>$actorId,'updated_by'=>$actorId]);$agreement->forceFill(['agreement_code'=>sprintf('HH-AGR-%06d',$agreement->id)])->saveQuietly();$this->copyAgencyAssets($agreement,$agency);$agreement->statusHistory()->create(['old_status'=>null,'new_status'=>'draft','changed_by'=>$actorId,'reason'=>'Agreement created']);return $agreement->fresh();});}
 public function update(Agreement $agreement,array $data,int $actorId):Agreement{if($agreement->status->isReadOnly())throw ValidationException::withMessages(['agreement'=>'Signed, active, expired, or cancelled agreements are read-only.']);return DB::transaction(function()use($agreement,$data,$actorId){$resolved=$this->resolve($data);$customer=$resolved['customer'];$assignment=$resolved['assignment'];$requirement=$resolved['requirement'];$worker=$resolved['worker'];$agreement->update(['customer_id'=>$customer->id,'customer_requirement_id'=>$requirement?->id,'assignment_id'=>$assignment?->id,'worker_id'=>$worker?->id,'service_id'=>$assignment?->service_id??$requirement?->service_id,'duty_type_id'=>$assignment?->duty_type_id??$requirement?->duty_type_id,'agreement_date'=>$data['agreement_date'],'start_date'=>$data['start_date']??null,'end_date'=>$data['end_date']??null,'tenure_text'=>$data['tenure_text']??$this->tenure($data['start_date']??null,$data['end_date']??null),'monthly_salary'=>$data['monthly_salary']??null,'monthly_agency_service_charge'=>$data['monthly_agency_service_charge']??null,'working_hours_text'=>$data['working_hours_text']??null,'monthly_leave_text'=>$data['monthly_leave_text']??null,'work_location'=>$data['work_location']??null,'gender_preference'=>$requirement?->required_gender,'house_type'=>$requirement?->householdDetail?->house_type,'terms_snapshot'=>$data['terms_snapshot'],'customer_name_snapshot'=>$data['customer_name_snapshot']??$customer->name,'customer_address_snapshot'=>$data['customer_address_snapshot']??$this->customerAddress($customer),'customer_mobile_snapshot'=>$data['customer_mobile_snapshot']??$customer->mobile_number,'customer_email_snapshot'=>$data['customer_email_snapshot']??$customer->email,'worker_name_snapshot'=>$worker?->name,'worker_code_snapshot'=>$worker?->worker_code,'authorized_person_name'=>$data['authorized_person_name']??$agreement->authorized_person_name,'updated_by'=>$actorId]);return $agreement->fresh();});}
 public function transition(Agreement $agreement,AgreementStatus $to,int $actorId,?string $reason=null):Agreement{return DB::transaction(function()use($agreement,$to,$actorId,$reason){$agreement=Agreement::lockForUpdate()->findOrFail($agreement->id);$allowed=['draft'=>['generated','cancelled'],'generated'=>['sent','cancelled'],'sent'=>['signed','cancelled'],'signed'=>['active'],'active'=>['expired'],'expired'=>[],'cancelled'=>[]];if(!in_array($to->value,$allowed[$agreement->status->value],true))throw ValidationException::withMessages(['status'=>'Invalid agreement status transition.']);$old=$agreement->status->value;$agreement->update(['status'=>$to,'updated_by'=>$actorId]);$agreement->statusHistory()->create(['old_status'=>$old,'new_status'=>$to->value,'changed_by'=>$actorId,'reason'=>$reason]);return $agreement->fresh();});}
 public function storeSignature(Agreement $agreement,string $party,array $data,int $actorId):Agreement{if(in_array($agreement->status,[AgreementStatus::Expired,AgreementStatus::Cancelled]))throw ValidationException::withMessages(['signature'=>'This agreement cannot be signed.']);return DB::transaction(function()use($agreement,$party,$data,$actorId){$dir="agreements/{$agreement->agreement_code}/signatures";$path=null;if(($data['signature']??null)instanceof UploadedFile)$path=$data['signature']->store($dir,'local');elseif(!empty($data['signature_data'])){$raw=preg_replace('#^data:image/(?:png|jpe?g|webp);base64,#i','',$data['signature_data']);$decoded=base64_decode(str_replace(' ','+',$raw),true);$image=$decoded===false?false:@getimagesizefromstring($decoded);if($image===false||!in_array($image['mime']??null,['image/png','image/jpeg','image/webp'],true))throw ValidationException::withMessages(['signature_data'=>'Invalid signature image.']);$path="$dir/{$party}-signature-".Str::random(8).'.png';Storage::disk('local')->put($path,$decoded);}if($party==='customer')$agreement->update(['customer_signature_path'=>$path,'customer_signed_at'=>now(),'updated_by'=>$actorId]);else{$stamp=($data['stamp']??null)instanceof UploadedFile?$data['stamp']->store($dir,'local'):$agreement->agency_stamp_path;$agreement->update(['agency_signature_path'=>$path?:$agreement->agency_signature_path,'agency_stamp_path'=>$stamp,'agency_signed_at'=>now(),'updated_by'=>$actorId]);}if($agreement->customer_signature_path&&$agreement->agency_signature_path&&$agreement->status===AgreementStatus::Sent)$this->transition($agreement,AgreementStatus::Signed,$actorId,'Both signatures captured');return $agreement->fresh();});}
 private function resolve(array $data):array{$assignment=!empty($data['assignment_id'])?Assignment::with(['customer','worker','requirement.workingCondition','requirement.householdDetail'])->findOrFail($data['assignment_id']):null;if($assignment){foreach(['customer_id'=>$assignment->customer_id,'customer_requirement_id'=>$assignment->customer_requirement_id,'worker_id'=>$assignment->worker_id] as $key=>$expected)if(!empty($data[$key])&&(int)$data[$key]!==$expected)throw ValidationException::withMessages([$key=>'Selection does not match the assignment.']);return ['assignment'=>$assignment,'customer'=>$assignment->customer,'requirement'=>$assignment->requirement,'worker'=>$assignment->worker];}$customer=Customer::findOrFail($data['customer_id']);$requirement=!empty($data['customer_requirement_id'])?CustomerRequirement::with(['workingCondition','householdDetail'])->findOrFail($data['customer_requirement_id']):null;if($requirement&&$requirement->customer_id!==$customer->id)throw ValidationException::withMessages(['customer_requirement_id'=>'Requirement does not belong to the selected customer.']);return ['assignment'=>null,'customer'=>$customer,'requirement'=>$requirement,'worker'=>!empty($data['worker_id'])?Worker::findOrFail($data['worker_id']):null];}
 private function tenure($start,$end):?string{if(!$start||!$end)return null;$s=Carbon::parse($start);$e=Carbon::parse($end);$months=(int)$s->diffInMonths($e);return $months>0?$months.' Month'.($months===1?'':'s'):$s->diffInDays($e).' Days';}
 private function customerAddress(Customer $c):string{return collect([$c->address_line_1,$c->address_line_2,$c->location,$c->city,$c->state,$c->pincode,$c->country])->filter()->join(', ');}private function agencyAddress(AgencySetting $a):string{return collect([$a->address_line_1,$a->address_line_2,$a->city,$a->state,$a->pincode,$a->country])->filter()->join(', ');}
 private function copyAgencyAssets(Agreement $a,AgencySetting $agency):void{foreach(['logo_path'=>'agency_logo_path','signature_path'=>'agency_signature_path','stamp_path'=>'agency_stamp_path'] as $source=>$target){$disk=$source==='logo_path'?'public':(Storage::disk('local')->exists((string)$agency->$source)?'local':'public');if($agency->$source&&Storage::disk($disk)->exists($agency->$source)){$ext=pathinfo($agency->$source,PATHINFO_EXTENSION)?:'png';$dest="agreements/{$a->agreement_code}/assets/{$target}.{$ext}";Storage::disk('local')->put($dest,Storage::disk($disk)->get($agency->$source));$a->updateQuietly([$target=>$dest]);}}}
}
